#!/usr/bin/env python3

import argparse
import json
import plistlib
import re
import sys
import tomllib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PALETTE_PATH = Path(__file__).with_suffix(".json")


def load_palette() -> dict:
    return json.loads(PALETTE_PATH.read_text())


def ghostty_theme(palette: dict) -> bytes:
    semantic = palette["semantic"]
    ansi = palette["ansi"]
    lines = [
        "# Generated by themes/kaile.py from themes/kaile.json.",
        f"background = {semantic['background']}",
        f"foreground = {semantic['foreground']}",
        f"cursor-color = {semantic['accent']}",
        f"cursor-text = {semantic['textOnAccent']}",
        f"selection-background = {semantic['surfaceSelection']}",
        f"selection-foreground = {semantic['textActive']}",
        "",
    ]
    lines.extend(f"palette = {index}={ansi[str(index)]}" for index in range(16))
    return ("\n".join(lines) + "\n").encode()


def iterm_color(value: str) -> dict:
    red, green, blue = (int(value[index : index + 2], 16) / 255 for index in (1, 3, 5))
    return {
        "Alpha Component": 1.0,
        "Blue Component": blue,
        "Color Space": "sRGB",
        "Green Component": green,
        "Red Component": red,
    }


def iterm_theme(palette: dict) -> bytes:
    semantic = palette["semantic"]
    ansi = palette["ansi"]
    colors = {f"Ansi {index} Color": iterm_color(ansi[str(index)]) for index in range(16)}
    colors.update(
        {
            "Background Color": iterm_color(semantic["background"]),
            "Bold Color": iterm_color(semantic["textActive"]),
            "Cursor Color": iterm_color(semantic["accent"]),
            "Cursor Guide Color": iterm_color(semantic["surfaceBorder"]),
            "Cursor Text Color": iterm_color(semantic["textOnAccent"]),
            "Foreground Color": iterm_color(semantic["foreground"]),
            "Selected Text Color": iterm_color(semantic["textActive"]),
            "Selection Color": iterm_color(semantic["surfaceSelection"]),
        }
    )
    return plistlib.dumps(colors, fmt=plistlib.FMT_XML, sort_keys=False)


