def outputs(palette: dict) -> dict[Path, bytes]:
    return {
        ROOT / "darwin/.config/ghostty/themes/kaile": ghostty_theme(palette),
        ROOT / "darwin/iterm2-themes/kaile.itermcolors": iterm_theme(palette),
        ROOT / "base/.config/nvim/lua/astrotheme/palettes/kaile.lua": nvim_palette(palette),
    }


def luminance(value: str) -> float:
    channels = [int(value[index : index + 2], 16) / 255 for index in (1, 3, 5)]
    linear = [channel / 12.92 if channel <= 0.04045 else ((channel + 0.055) / 1.055) ** 2.4 for channel in channels]
    return 0.2126 * linear[0] + 0.7152 * linear[1] + 0.0722 * linear[2]


def contrast(foreground: str, background: str) -> float:
    lighter, darker = sorted((luminance(foreground), luminance(background)), reverse=True)
    return (lighter + 0.05) / (darker + 0.05)


def resolve(palette: dict, reference: str) -> str:
    section, key = reference.split(".", 1)
    return palette[section][key]


def validate_contrast(palette: dict) -> list[str]:
    errors = []
    for pair in palette["contrastPairs"]:
        foreground = resolve(palette, pair["foreground"])
        background = resolve(palette, pair["background"])
        ratio = contrast(foreground, background)
        if ratio < pair["minimum"]:
            errors.append(
                f"{pair['name']}: {ratio:.2f}:1 is below {pair['minimum']:.2f}:1 "
                f"({foreground} on {background})"
            )
    return errors


def validate_manual_consumers(palette: dict) -> list[str]:
    errors = []
    semantic = palette["semantic"]
    allowed = {value.lower() for value in semantic.values()} | {
        value.lower() for value in palette["ansi"].values()
    }

    vscode_path = ROOT / "darwin/vscode/extensions/kaile-theme/themes/kaile-color-theme.json"
    for value in set(re.findall(r"#[0-9a-fA-F]{6,8}", vscode_path.read_text())):
        if value[:7].lower() not in allowed:
            errors.append(f"{vscode_path.relative_to(ROOT)} uses unknown color {value}")

    herdr_path = ROOT / "ai/herdr/config.toml"
    herdr = tomllib.loads(herdr_path.read_text())["theme"]["custom"]
    expected = {
        "active_row_bg": semantic["surfaceActive"],
        "selection_bg": semantic["surfaceSelection"],
        "surface0": semantic["surfaceRaised"],
        "surface1": semantic["surfaceActive"],
        "surface_dim": semantic["textOnBlue"],
    }
    if herdr != expected:
        errors.append(f"{herdr_path.relative_to(ROOT)} does not match semantic Kaile roles")
    return errors


def write_outputs(palette: dict) -> None:
    for path, content in outputs(palette).items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(content)
        print(f"wrote {path.relative_to(ROOT)}")


def check_outputs(palette: dict) -> int:
    errors = validate_contrast(palette) + validate_manual_consumers(palette)
    for path, expected in outputs(palette).items():
        if not path.exists() or path.read_bytes() != expected:
            errors.append(f"{path.relative_to(ROOT)} is not generated from themes/kaile.json")
    if errors:
        print("Kaile palette check failed:", file=sys.stderr)
        for error in errors:
            print(f"- {error}", file=sys.stderr)
        return 1
    print("Kaile palette: generated files and semantic contrast pairs are valid")
    return 0


def main() -> int:
    parser = argparse.ArgumentParser(description="Generate and validate the Kaile color palette")
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--write", action="store_true", help="regenerate consumer theme files")
    mode.add_argument("--check", action="store_true", help="verify generated files and contrast")
    args = parser.parse_args()
    palette = load_palette()
    if args.write:
        write_outputs(palette)
        return 0
    return check_outputs(palette)


if __name__ == "__main__":
    raise SystemExit(main())
